cmd = [
    "cc",
    *flags,
    "-w",
    "-DSTANDALONE",
    "-DHAVE_MOBILE",
    "-DXSHIM_NATIVE",
    f"-I{out}",
    f"-I{src}",
    f"-I{src / 'x11shim/include'}",
    f"-I{src / 'xs_support'}",
    f"-I{src / 'xs_support/glx'}",
    f"-I{generated / 'tinygl/include'}",
    f"-I{generated}",
